"""Cache coherence boundaries, overload controls, metastable failures, telemetry, and SLO policy."""

WORLD = "sw-system-design-reliability-v0"
PREFIX = "sys"
DOMAIN = "distributed-cloud-data"
SUBJECT = "distributed-cloud-data.site-reliability"
SOURCES = ["google-sre-2016", "google-sre-workbook-2018", "bronson-2021-metastable-failures", "rfc9111", "google-dapper-2010"]
SCOPE = "Google SRE 2016 and Workbook 2018 reliability guidance, the original HotOS 2021 metastable-failure model, RFC 9111 HTTP caching, and original Dapper 2010 tracing, alongside explicitly declared cache-publication, token-bucket, queue, breaker, bulkhead, deadline and error-budget policies rather than unverified library behavior."
ROOT_LABEL = "System design reliability causation world"
ROOT_STATEMENT = "Root of the system design reliability causation world: how cache and admission rules, resource occupancy, recovery feedback, measurement choices and enforced service policies change specific work, failure and observation outcomes under stated scopes."
LIMITATIONS = [
    "All prose is original. HTTP freshness and cache reuse permissions are distinct from application-version coherence; local request coalescing does not coordinate independent service instances.",
    "Circuit-breaker generations, trial permits, bulkhead partitions and publication epochs use the exact declared local policies. They are not attributed to a universal framework implementation or to an unread stability-pattern source.",
    "Rate, concurrency, queue and work budgets constrain their named populations and boundaries. Rejected traffic still reaches some admission machinery, and caller timeout does not by itself end remote resource use.",
    "Metastability means the modeled amplification can sustain the degraded regime after its initiating trigger is removed. It is not a synonym for every prolonged outage, transient burst or slow recovery.",
    "Log records, aggregates and sampled parent-linked spans describe different observed populations. Declared collision-free correlation identities are a model premise, not a claim that Dapper's finite identifiers have mathematically zero collision probability or that trace association proves physical causation.",
    "SLIs, targets, windows and budget arithmetic are separated from the named policy that admits a release or raises an alert. No universal deployment prohibition, sample completeness or exact production latency is inferred from those metrics alone.",
]

